import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "../styles/Cart.css";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";

const Cart = () => {
  const navigate = useNavigate();
  const [cartItems, setCartItems] = useState([]);
  const [shipping, setShipping] = useState(0);

  useEffect(() => {
    const stored = JSON.parse(sessionStorage.getItem("cartItems") || "[]");
    setCartItems(stored);
    setShipping(parseFloat((Math.random() * 4 + 3).toFixed(2))); // $3–$7
  }, []);

  const subtotal = cartItems.reduce((sum, item) => sum + parseFloat(item.price), 0);
  const tax = parseFloat((subtotal * 0.08).toFixed(2));
  const total = parseFloat((subtotal + tax + shipping).toFixed(2));

  const goToCheckout = () => {
    const orderSummary = { items: cartItems, subtotal, tax, shipping, total };
    sessionStorage.setItem("orderSummary", JSON.stringify(orderSummary));
    navigate("/checkout");
  };

  return (
    <div className="cart-wrapper">
      <Navbar />
      <div className="cart-main">
        <div className="cart-items">
          <h2>🛒 Your Cart</h2>
          {cartItems.length === 0 ? (
            <p>No items in cart</p>
          ) : (
            cartItems.map((item, index) => (
              <div className="cart-item" key={index}>
                <img src={item.image} alt={item.title} />
                <div>
                  <h3>{item.title}</h3>
                  <p>${item.price}</p>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="cart-summary">
          <h3>Order Summary</h3>
          <p>Subtotal: ${subtotal.toFixed(2)}</p>
          <p>Tax (8%): ${tax}</p>
          <p>Shipping: ${shipping}</p>
          <hr />
          <p><strong>Total: ${total}</strong></p>
          <button onClick={goToCheckout}>Proceed to Checkout</button>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default Cart;
